-- places/districts
-- All 77 districts with both names, for the district select on the report form.
-- The page sorts them in the visitor's language.
--
-- No parameters.
--
-- Generated by `pnpm db:queries` from lib/db/queries/places.ts. Do not edit by hand.

select "districts"."id", "districts"."slug", "districts"."name_en", "districts"."name_np", "provinces"."code"
from "districts"
inner join "provinces" on "provinces"."id" = "districts"."province_id"
order by "districts"."name_en" asc;
